refentry.refsect1:
&reftitle.returnvalues;


 Restituisce una string. Restituisce una stringa vuota se non ci sono errori. Se c'è un errore associato al
 parametro result, restituisce &false;.

  &reftitle.examples;



    Esempio di pg_result_error


<?php
  $dbconn = pg_connect("dbname=publisher") or die("Impossibile connettersi");

  if (!pg_connection_busy($dbconn)) {
      pg_send_query($dbconn, "select * from doesnotexist;");
  }

  $res1 = pg_get_result($dbconn);
  echo pg_result_error($res1);
?>
